const D=window.CREATOR_COMMERCE_DEMO,R=D.contentResults,C=D.creators,SKU=D.sku,CAMP=D.campaign;
const $=id=>document.getElementById(id),money=n=>'R$ '+Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
let rows=[...R.contents],openContentId=null,sort={key:'revenue',desc:true};
const creator=id=>C.find(x=>x.id===id);
const typeLabel=t=>t==='VIDEO'?'Vídeo':t;
function creatorContentRows(id){return rows.filter(x=>x.creatorId===id&&x.campaignScope)}
function creatorFixedCosts(id){const c=creator(id);return Number(c?.activation?.sampleCost||0)+Number(c?.activation?.shippingCost||0)}
function metrics(x){
  const c=creator(x.creatorId),group=creatorContentRows(x.creatorId),groupRevenue=group.reduce((a,v)=>a+v.revenue,0)||1,fixed=creatorFixedCosts(x.creatorId)*(x.revenue/groupRevenue);
  const baseMargin=x.revenue*SKU.baseMarginPct/100,commission=x.revenue*c.cm/100,margin=baseMargin-commission-fixed;
  return {conversion:x.views?x.orders/x.views*100:0,rpm:x.views?x.revenue/x.views*1000:0,margin,marginPct:x.revenue?margin/x.revenue*100:0,fixed}
}
function totals(){return rows.reduce((a,x)=>{const m=metrics(x);a.orders+=x.orders;a.revenue+=x.revenue;a.settledOrders+=x.settledOrders;a.settledRevenue+=x.settledRevenue;a.provisionalOrders+=x.provisionalOrders;a.provisionalRevenue+=x.provisionalRevenue;a.margin+=m.margin;return a},{orders:0,revenue:0,settledOrders:0,settledRevenue:0,provisionalOrders:0,provisionalRevenue:0,margin:0})}
function spark(values,cls='spark'){const max=Math.max(...values,1),w=100,h=34,pts=values.map((v,i)=>(i*(w/(values.length-1)))+','+(h-(v/max*(h-4)+2))).join(' ');return "<svg class='"+cls+"' viewBox='0 0 "+w+" "+h+"' preserveAspectRatio='none'><polyline points='"+pts+"'/></svg>"}
function renderSummary(){const t=totals(),pct=t.orders?t.settledOrders/t.orders*100:0;$('attrRevenue').textContent=money(t.revenue);$('attrOrders').textContent=t.orders+' pedidos atribuídos';$('settledOrders').textContent=t.settledOrders;$('settledRevenue').textContent=money(t.settledRevenue);$('provOrders').textContent=t.provisionalOrders;$('provRevenue').textContent=money(t.provisionalRevenue);$('attrMargin').textContent=money(t.margin);$('attrMarginPct').textContent=(t.revenue?t.margin/t.revenue*100:0).toFixed(1).replace('.',',')+'% da receita atribuída';$('settledPct').textContent=pct.toFixed(1).replace('.',',')+'%';$('provPct').textContent=(100-pct).toFixed(1).replace('.',',')+'%';$('settledBar').style.width=pct+'%'}
function filteredRows(){const q=$('globalSearch').value.toLowerCase().trim(),type=$('typeFilter').value,cid=$('creatorFilter').value;return rows.filter(x=>{const c=creator(x.creatorId);return (!q||(x.title+' '+c.n+' '+x.type).toLowerCase().includes(q))&&(type==='all'||x.type===type)&&(cid==='all'||String(x.creatorId)===cid)})}
function sortValue(x,key){const m=metrics(x);return key==='conversion'?m.conversion:key==='rpm'?m.rpm:key==='margin'?m.margin:Number(x[key]||0)}
function renderRows(){const visible=filteredRows().slice().sort((a,b)=>(sortValue(a,sort.key)-sortValue(b,sort.key))*(sort.desc?-1:1));$('contentRows').innerHTML=visible.map(x=>{const c=creator(x.creatorId),m=metrics(x);return "<tr><td><div class='contentCell'><div class='thumb "+(x.type==='LIVE'?'live':'video')+"'>"+typeLabel(x.type)+"</div><div><b>"+x.title+"</b><div class='sub'>"+x.source+" · Atualizado há "+x.freshness+"</div></div></div></td><td>"+c.n+"</td><td>"+x.publishedAt+"</td><td>"+x.views.toLocaleString('pt-BR')+"</td><td>"+x.orders+"</td><td>"+m.conversion.toFixed(3).replace('.',',')+"%</td><td>"+money(m.rpm)+"</td><td>"+x.settledOrders+"</td><td>"+x.provisionalOrders+"</td><td>"+money(x.revenue)+"</td><td><b>"+money(m.margin)+"</b><div class='sub'>"+m.marginPct.toFixed(1).replace('.',',')+"% · provisória</div></td><td>"+spark(x.dailyRevenue)+"</td><td><button class='btn detail' data-id='"+x.id+"'>Abrir</button></td></tr>"}).join('');document.querySelectorAll('.detail').forEach(b=>b.onclick=()=>openDetail(b.dataset.id))}
function renderContext(){const t=totals();$('businessOrders').textContent=R.businessContext.orders;$('businessRevenue').textContent=money(R.businessContext.revenue);$('businessPeriod').textContent=R.businessContext.period;$('businessSource').textContent=R.businessContext.source;$('businessFreshness').textContent='Atualizado há '+R.businessContext.freshness;$('attributedShare').textContent=(t.revenue/R.businessContext.revenue*100).toFixed(1).replace('.',',')+'%'}
function renderCreatorSummary(){const ids=[...new Set(rows.map(x=>x.creatorId))];$('creatorSummary').innerHTML=ids.map(id=>{const c=creator(id),rs=creatorContentRows(id),revenue=rs.reduce((a,x)=>a+x.revenue,0),orders=rs.reduce((a,x)=>a+x.orders,0),views=rs.reduce((a,x)=>a+x.views,0),provisional=rs.reduce((a,x)=>a+x.provisionalOrders,0),margin=rs.reduce((a,x)=>a+metrics(x).margin,0);return "<div class='creatorSummaryRow'><div><b>"+c.n+"</b><div class='sub'>"+c.h+" · "+rs.length+" conteúdos</div></div><div><span class='sub'>Views</span><br><b class='big'>"+views.toLocaleString('pt-BR')+"</b></div><div><span class='sub'>Pedidos</span><br><b class='big'>"+orders+"</b></div><div><span class='sub'>Receita</span><br><b class='big'>"+money(revenue)+"</b></div><div><span class='sub'>Margem</span><br><b class='big'>"+money(margin)+"</b><div class='sub'>"+(margin/revenue*100).toFixed(1).replace('.',',')+"%</div></div><div><span class='sub'>Estado</span><br><span class='badge amber'>Lucro incompleto · "+provisional+" provisórios</span></div></div>"}).join('')}
function renderLearning(){$('learningRows').innerHTML=R.learning.map(x=>{const c=creator(x.creatorId);return "<div class='learningRow'><div class='creator'>"+c.n+"<div class='sub'>"+c.h+"</div></div><div><span class='sub'>Recomendação</span><br><b>"+x.recommendation+"</b></div><div><span class='sub'>Decisão</span><br><b>"+x.decision+"</b></div><div><span class='sub'>Ação</span><br>"+x.action+"</div><div><span class='sub'>Resultado</span><br>"+x.result+"</div><div class='reuse'><b>Reutilização</b><br>"+x.reuse+"</div></div>"}).join('')}
function renderCampaignTruth(){const camila=creator(3);$('campaignName').textContent=CAMP.name;$('campaignOrders').textContent=camila.activation.orders;$('campaignRevenue').textContent=money(camila.activation.revenue)}
function openDetail(id){const x=rows.find(v=>v.id===id),c=creator(x.creatorId),m=metrics(x);openContentId=id;$('detailTitle').textContent=x.title;$('detailMeta').textContent=c.n+' · '+x.publishedAt+' · '+x.source;$('detailPreview').innerHTML="<div class='thumb "+(x.type==='LIVE'?'live':'video')+"' style='width:100%;height:100%;border-radius:12px'>"+typeLabel(x.type)+"</div>";$('detailTrend').innerHTML=spark(x.dailyRevenue,'spark detailSpark');$('detailViews').textContent=x.views.toLocaleString('pt-BR');$('detailOrders').textContent=x.orders;$('detailConversion').textContent=m.conversion.toFixed(3).replace('.',',')+'%';$('detailRpm').textContent=money(m.rpm);$('detailSettled').textContent=x.settledOrders;$('detailProv').textContent=x.provisionalOrders;$('detailRevenue').textContent=money(x.revenue);$('detailMargin').textContent=money(m.margin)+' · '+m.marginPct.toFixed(1).replace('.',',')+'% · provisória';$('detailSource').textContent=x.source;$('detailFreshness').textContent='Atualizado há '+x.freshness;const b=$('openPublishedContent');b.disabled=!x.link;b.title=x.link?'Abrir conteúdo original':x.linkReason;b.textContent=x.link?'Abrir conteúdo publicado':'Link indisponível neste DEMO';$('modalOverlay').classList.add('show');$('detailModal').classList.add('show')}
function close(){$('modalOverlay').classList.remove('show');$('detailModal').classList.remove('show')}
$('closeDetail').onclick=close;$('modalOverlay').onclick=close;$('globalSearch').oninput=renderRows;$('typeFilter').onchange=renderRows;$('creatorFilter').onchange=renderRows;$('openPublishedContent').onclick=()=>{const x=rows.find(v=>v.id===openContentId);if(x?.link)location.href=x.link};
document.querySelectorAll('th.sortable').forEach(th=>th.onclick=()=>{const key=th.dataset.sort;if(sort.key===key)sort.desc=!sort.desc;else{sort={key,desc:true}}renderRows();toast('Ordenado por '+th.textContent.replace('↕','').trim())});
$('periodBtn').onclick=()=>toast('Período fixado em 30 dias neste protótipo');$('userBtn').onclick=()=>toast('Workspace Principal · Daniel Santos');$('market').onchange=()=>toast('Somente Brasil · TikTok Shop disponível neste protótipo');
$('openEconomics').onclick=()=>location.href='../unit-economics/index.html';$('openCampaign').onclick=()=>location.href='../campaign/index.html';$('showLearning').onclick=()=>{$('learningCard').scrollIntoView({behavior:'smooth'});$('learningCard').classList.add('focus');setTimeout(()=>$('learningCard').classList.remove('focus'),1200)};
$('navSku').onclick=()=>location.href='../sku-opportunity/index.html';$('navShortlist').onclick=()=>location.href='../creator-shortlist/index.html';$('navOutreach').onclick=()=>location.href='../outreach/index.html';$('navCampaign').onclick=()=>location.href='../campaign/index.html';$('navEconomics').onclick=()=>location.href='../unit-economics/index.html';
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',1600)}
[...new Map(rows.map(x=>[x.creatorId,creator(x.creatorId)])).values()].forEach(c=>$('creatorFilter').insertAdjacentHTML('beforeend',"<option value='"+c.id+"'>"+c.n+"</option>"));
renderSummary();renderContext();renderRows();renderCreatorSummary();renderLearning();renderCampaignTruth();